import { BrowserRouter, Routes, Route } from 'react-router-dom';
import PreviousOrders from './pages/PreviousOrders';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/orders" element={<PreviousOrders />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
